generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:riskTolerance ?riskTol ;
       wm:hasInvestmentGoal ?goal ;
       wm:hasHolding ?hold ;
       wm:hasPortfolioHealth ?ph ;
       wm:hasSectorAllocation ?alloc .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  FILTER(LCASE(STR(?riskTol)) = "aggressive")

  # Underfunded goal
  ?goal a wm:InvestmentGoal ;
        wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0)

  # Gold holding
  ?hold a wm:PortfolioHolding ;
        wm:investmentName ?invHoldingName .
  FILTER(CONTAINS(LCASE(STR(?invHoldingName)), "gold"))

  # Risk score above 60
  ?ph a wm:PortfolioHealth ;
      wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 60)

  # Sector allocation above 30%
  ?alloc a wm:SectorAllocation ;
         wm:allocationPct ?allocPct .
  FILTER(xsd:decimal(?allocPct) > 30)
}

